public class Solution {
    static void mergeSort(int[] a) {
        sort(a, new int[a.length], 0, a.length);
    }

    // Ordena [lo, hi). O buffer é compartilhado por todas as chamadas.
    private static void sort(int[] a, int[] buf, int lo, int hi) {
        if (hi - lo < 2) return;
        int mid = (lo + hi) >>> 1;
        sort(a, buf, lo, mid);
        sort(a, buf, mid, hi);
        if (a[mid - 1] <= a[mid]) return; // já ordenado
        System.arraycopy(a, lo, buf, lo, hi - lo);
        int i = lo, j = mid, k = lo;
        while (i < mid && j < hi) a[k++] = buf[i] <= buf[j] ? buf[i++] : buf[j++]; // <= mantém estável
        while (i < mid) a[k++] = buf[i++];
        while (j < hi) a[k++] = buf[j++];
    }
}

