import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    @Test void pequenos() {
        int[] a = {5, -1, 3, 3, 0, 9, -7};
        Solution.mergeSort(a);
        assertArrayEquals(new int[]{-7, -1, 0, 3, 3, 5, 9}, a);
        int[] vazio = {};
        Solution.mergeSort(vazio);
        assertEquals(0, vazio.length);
    }

    @Test void milhaoAleatorio() {
        int[] a = new Random(1).ints(1_000_000).toArray();
        int[] ref = a.clone();
        Arrays.sort(ref);
        Solution.mergeSort(a);
        assertArrayEquals(ref, a);
    }

    @Test void ordenadoEInvertido() {
        int[] a = new int[200_000];
        for (int i = 0; i < a.length; i++) a[i] = a.length - i;
        Solution.mergeSort(a);
        for (int i = 0; i < a.length; i++) assertEquals(i + 1, a[i]);
    }
}

