import java.util.concurrent.ThreadLocalRandom;

public class Solution {
    static void quickSort(int[] a) { sort(a, 0, a.length - 1); }

    // Invariante: [lo, lt) < p, [lt, i) == p, (gt, hi] > p. Recursão só nas pontas.
    private static void sort(int[] a, int lo, int hi) {
        while (lo < hi) {
            int p = a[ThreadLocalRandom.current().nextInt(lo, hi + 1)];
            int lt = lo, i = lo, gt = hi;
            while (i <= gt) {
                if (a[i] < p) swap(a, lt++, i++);
                else if (a[i] > p) swap(a, i, gt--);
                else i++;
            }
            // Recursão no lado menor, laço no maior: pilha O(log n).
            if (lt - lo < hi - gt) {
                sort(a, lo, lt - 1);
                lo = gt + 1;
            } else {
                sort(a, gt + 1, hi);
                hi = lt - 1;
            }
        }
    }

    private static void swap(int[] a, int i, int j) { int t = a[i]; a[i] = a[j]; a[j] = t; }
}

