import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    @Test void pequenos() {
        int[] a = {3, 1, 2, 3, 3, 0, -5};
        Solution.quickSort(a);
        assertArrayEquals(new int[]{-5, 0, 1, 2, 3, 3, 3}, a);
    }

    @Test void muitosRepetidos() {
        int[] a = new Random(2).ints(1_000_000, 0, 3).toArray();
        int[] ref = a.clone();
        Arrays.sort(ref);
        Solution.quickSort(a);
        assertArrayEquals(ref, a);
    }

    @Test void jaOrdenadoETodosIguais() {
        int[] a = new int[500_000];
        for (int i = 0; i < a.length; i++) a[i] = i;
        Solution.quickSort(a);
        assertEquals(499_999, a[499_999]);
        int[] iguais = new int[500_000];
        Arrays.fill(iguais, 7);
        Solution.quickSort(iguais);
        assertEquals(7, iguais[0]);
    }

    @Test void aleatorio() {
        int[] a = new Random(9).ints(1_000_000).toArray();
        int[] ref = a.clone();
        Arrays.sort(ref);
        Solution.quickSort(a);
        assertArrayEquals(ref, a);
    }
}
